            method: method,
            headers: {
                "content-type": "application/json",
                "pls-prime-tenant-session": PLS_PRIME_TENANT_SESSION
                    ? PLS_PRIME_TENANT_SESSION
                    : "",
                "pls-session": PLS_SESSION ? PLS_SESSION : "",
            },
            cache: "no-cache",
            body: JSON.stringify(requestBody),
            credentials: "include",
